/*
 * trace_bvh_hip.h — HIP kernel source (compiled at runtime by hiprtc) for the
 * LightRT HIP backend. This is a direct port of vk/shaders/trace_bvh.comp: one
 * thread = one ray, traversing the SAME serialized LRTS node/block memory image
 * the C builder produces (lrt_tri_scene_save_to_memory), so hits match the CPU
 * and Vulkan-compute paths within fp tolerance.
 *
 * Unlike the SPIR-V shader (which selects the SoA lane width W and the traversal
 * stack depth via spec constants), this kernel takes W and the stack limit as
 * launch arguments and uses a fixed 256-entry stack (the largest bucket
 * trace_stack_for can return), so a single compiled kernel serves BVH4 and BVH8.
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#ifndef LIGHTRT_TRACE_BVH_HIP_H
#define LIGHTRT_TRACE_BVH_HIP_H

/* NOTE: no #include <hip/hip_runtime.h> — hiprtc (like NVRTC) preincludes the
 * device runtime, so the include is not on its search path and the builtins
 * (blockIdx/threadIdx, __uint_as_float, fminf/fmaxf) are already available. */
static const char *const k_lrt_hip_trace_bvh_src =
    "#define LEAF_BIT 0x80000000u\n"
    "#define NO_HIT   0xFFFFFFFFu\n"
    "#define INVD_MAX 1e18f\n"
    "#define MAX_STACK 256\n"
    "\n"
    "extern \"C\" __global__ void lrt_hip_trace_bvh(\n"
    "    const unsigned int* __restrict__ nodes,\n"
    "    const unsigned int* __restrict__ blocks,\n"
    "    const unsigned int* __restrict__ rays,\n"
    "    unsigned int* __restrict__ hits,\n"
    "    unsigned int root, unsigned int ray_count,\n"
    "    unsigned int W, unsigned int stack_limit) {\n"
    "  unsigned int gid = blockIdx.x * blockDim.x + threadIdx.x;\n"
    "  if (gid >= ray_count) return;\n"
    "\n"
    "  unsigned int rb = gid * 8u;\n"
    "  float orgx = __uint_as_float(rays[rb + 0u]);\n"
    "  float orgy = __uint_as_float(rays[rb + 1u]);\n"
    "  float orgz = __uint_as_float(rays[rb + 2u]);\n"
    "  float tmin = __uint_as_float(rays[rb + 3u]);\n"
    "  float dirx = __uint_as_float(rays[rb + 4u]);\n"
    "  float diry = __uint_as_float(rays[rb + 5u]);\n"
    "  float dirz = __uint_as_float(rays[rb + 6u]);\n"
    "  float tmax = __uint_as_float(rays[rb + 7u]);\n"
    "\n"
    "  float dir[3] = {dirx, diry, dirz};\n"
    "  float org[3] = {orgx, orgy, orgz};\n"
    "  float invd[3];\n"
    "  for (int k = 0; k < 3; k++) {\n"
    "    float d = dir[k];\n"
    "    float inv = 1.0f / d;\n"
    "    if (!(inv >= -INVD_MAX && inv <= INVD_MAX)) {\n"
    "      float s = (d == 0.0f) ? 1.0f : d;\n"
    "      inv = (s < 0.0f) ? -INVD_MAX : INVD_MAX;\n"
    "    }\n"
    "    invd[k] = inv;\n"
    "  }\n"
    "\n"
    "  float best_t = tmax;\n"
    "  float best_u = 0.0f, best_v = 0.0f;\n"
    "  unsigned int best_prim = NO_HIT;\n"
    "\n"
    "  unsigned int node_stride = 8u * W;\n"
    "  unsigned int block_stride = 10u * W;\n"
    "  unsigned int prim_off = 9u * W;\n"
    "\n"
    "  unsigned int stk_ref[MAX_STACK];\n"
    "  float stk_tn[MAX_STACK];\n"
    "  int sp = 0;\n"
    "  stk_ref[0] = root;\n"
    "  stk_tn[0] = tmin;\n"
    "  sp = 1;\n"
    "\n"
    "  while (sp > 0) {\n"
    "    sp--;\n"
    "    unsigned int ref = stk_ref[sp];\n"
    "    float tnear_e = stk_tn[sp];\n"
    "    if (tnear_e >= best_t) continue;\n"
    "\n"
    "    if ((ref & LEAF_BIT) != 0u) {\n"
    "      unsigned int blk0 = (ref & 0x7FFFFFFFu) >> 4u;\n"
    "      unsigned int nblk = ref & 0xFu;\n"
    "      for (unsigned int b = 0u; b < nblk; b++) {\n"
    "        unsigned int bb = (blk0 + b) * block_stride;\n"
    "        for (unsigned int lane = 0u; lane < W; lane++) {\n"
    "          unsigned int prim = blocks[bb + prim_off + lane];\n"
    "          if (prim == NO_HIT) continue;\n"
    "          float v0x = __uint_as_float(blocks[bb + 0u * W + lane]);\n"
    "          float v0y = __uint_as_float(blocks[bb + 1u * W + lane]);\n"
    "          float v0z = __uint_as_float(blocks[bb + 2u * W + lane]);\n"
    "          float e1x = __uint_as_float(blocks[bb + 3u * W + lane]);\n"
    "          float e1y = __uint_as_float(blocks[bb + 4u * W + lane]);\n"
    "          float e1z = __uint_as_float(blocks[bb + 5u * W + lane]);\n"
    "          float e2x = __uint_as_float(blocks[bb + 6u * W + lane]);\n"
    "          float e2y = __uint_as_float(blocks[bb + 7u * W + lane]);\n"
    "          float e2z = __uint_as_float(blocks[bb + 8u * W + lane]);\n"
    "          float px = dir[1] * e2z - dir[2] * e2y;\n"
    "          float py = dir[2] * e2x - dir[0] * e2z;\n"
    "          float pz = dir[0] * e2y - dir[1] * e2x;\n"
    "          float det = e1x * px + e1y * py + e1z * pz;\n"
    "          if (det > -1e-12f && det < 1e-12f) continue;\n"
    "          float inv_det = 1.0f / det;\n"
    "          float tvx = org[0] - v0x;\n"
    "          float tvy = org[1] - v0y;\n"
    "          float tvz = org[2] - v0z;\n"
    "          float uu = (tvx * px + tvy * py + tvz * pz) * inv_det;\n"
    "          if (uu < 0.0f || uu > 1.0f) continue;\n"
    "          float qx = tvy * e1z - tvz * e1y;\n"
    "          float qy = tvz * e1x - tvx * e1z;\n"
    "          float qz = tvx * e1y - tvy * e1x;\n"
    "          float vv = (dir[0] * qx + dir[1] * qy + dir[2] * qz) * inv_det;\n"
    "          if (vv < 0.0f || uu + vv > 1.0f) continue;\n"
    "          float tt = (e2x * qx + e2y * qy + e2z * qz) * inv_det;\n"
    "          if (tt < tmin || tt >= best_t) continue;\n"
    "          best_t = tt; best_u = uu; best_v = vv; best_prim = prim;\n"
    "        }\n"
    "      }\n"
    "      continue;\n"
    "    }\n"
    "\n"
    "    unsigned int nb = (ref & 0x7FFFFFFFu) * node_stride;\n"
    "    unsigned int nchildren = nodes[nb + 7u * W];\n"
    "\n"
    "    unsigned int hit_ref[8];\n"
    "    float hit_tn[8];\n"
    "    int nhit = 0;\n"
    "    for (unsigned int i = 0u; i < nchildren; i++) {\n"
    "      float lo_x = __uint_as_float(nodes[nb + 0u * W + i]);\n"
    "      float lo_y = __uint_as_float(nodes[nb + 1u * W + i]);\n"
    "      float lo_z = __uint_as_float(nodes[nb + 2u * W + i]);\n"
    "      float hi_x = __uint_as_float(nodes[nb + 3u * W + i]);\n"
    "      float hi_y = __uint_as_float(nodes[nb + 4u * W + i]);\n"
    "      float hi_z = __uint_as_float(nodes[nb + 5u * W + i]);\n"
    "      float tlx = (lo_x - org[0]) * invd[0];\n"
    "      float thx = (hi_x - org[0]) * invd[0];\n"
    "      float tly = (lo_y - org[1]) * invd[1];\n"
    "      float thy = (hi_y - org[1]) * invd[1];\n"
    "      float tlz = (lo_z - org[2]) * invd[2];\n"
    "      float thz = (hi_z - org[2]) * invd[2];\n"
    "      float tnx = fminf(tlx, thx), tfx = fmaxf(tlx, thx);\n"
    "      float tny = fminf(tly, thy), tfy = fmaxf(tly, thy);\n"
    "      float tnz = fminf(tlz, thz), tfz = fmaxf(tlz, thz);\n"
    "      float tnear = fmaxf(fmaxf(tnx, tny), fmaxf(tnz, tmin));\n"
    "      float tfar = fminf(fminf(tfx, tfy), fminf(tfz, best_t));\n"
    "      if (tnear <= tfar) {\n"
    "        int j = nhit++;\n"
    "        while (j > 0 && hit_tn[j - 1] > tnear) {\n"
    "          hit_tn[j] = hit_tn[j - 1];\n"
    "          hit_ref[j] = hit_ref[j - 1];\n"
    "          j--;\n"
    "        }\n"
    "        hit_tn[j] = tnear;\n"
    "        hit_ref[j] = nodes[nb + 6u * W + i];\n"
    "      }\n"
    "    }\n"
    "    if ((unsigned int)sp + (unsigned int)nhit > stack_limit) {\n"
    "      best_prim = NO_HIT; break;\n"
    "    }\n"
    "    for (int i = nhit - 1; i >= 0; i--) {\n"
    "      stk_ref[sp] = hit_ref[i];\n"
    "      stk_tn[sp] = hit_tn[i];\n"
    "      sp++;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  unsigned int hb = gid * 4u;\n"
    "  hits[hb + 0u] = __float_as_uint(best_prim != NO_HIT ? best_t : 0.0f);\n"
    "  hits[hb + 1u] = __float_as_uint(best_u);\n"
    "  hits[hb + 2u] = __float_as_uint(best_v);\n"
    "  hits[hb + 3u] = best_prim;\n"
    "}\n";

#endif /* LIGHTRT_TRACE_BVH_HIP_H */
